#include <stdio.h>

int main(void) {
    char word[64];

    if (scanf("%s", word) != 1) {
        return 1;
    }

    int n = 0;
    for (char *p = word; *p != '\0'; p++) {
        printf("%c\n", *p);
        n = n + 1;
    }
    printf("一共 %d 颗珠子\n", n);
    return 0;
}
